INSERT INTO `profiles` (`id`, `sejarah`, `visi_misi`, `geografi`, `batas_wilayah`, `peta_embed`, `stats_suhu`, `stats_ketinggian`, `stats_hujan`, `stats_luas`, `created_at`, `updated_at`, `sejarah_timeline`, `visi`, `misi`, `geografi_stats`, `batas_wilayah_json`, `peta_deskripsi`, `peta_rute_pribadi`, `peta_rute_umum`, `hero_sejarah`, `hero_visimisi`, `hero_geografi`, `hero_peta`, `motto`, `dusun_info`, `peta_image`, `peta_narasi_utama`, `peta_narasi_legenda`, `peta_fasilitas`, `sejarah_image`, `peta_identitas`, `peta_teknis`, `peta_koordinat`, `peta_batas_administrasi`, `peta_legenda`, `peta_kantor`, `peta_kartometrik`, `peta_sumber`) VALUES
('1', 'Desa Selorejo yang dikenal saat ini awalnya memiliki akar sejarah yang kuat dengan nama "Watugedhe". Nama ini merujuk pada keberadaan dua batu raksasa tak lazim yang dipercaya memiliki daya mistis (hingga kini batu tersebut masih berada di lokasi aslinya). Perjalanan desa ini dimulai sekitar pertengahan abad ke-18 pasca Perang Diponegoro. Para pionir, yakni Mbah H. Turejo dan Mbah Sayang, bersama rombongan pelarian dari Mataram Islam yang melawan kolonial Belanda, melakukan "Babat Alas" atau pembukaan lahan di tengah hutan lebat lereng gunung sebagai hunian baru.
