INSERT INTO `wisata` (`id`, `judul`, `deskripsi`, `harga_tiket`, `jadwal`, `aturan`, `gambar`, `created_at`, `updated_at`, `kategori`, `likes`, `dislikes`, `views`, `shares`, `whatsapp`) VALUES
('1', 'Agrowisata Petik Jeruk Selorejo', 'Menjadi ikon utama Wisata Desa Selorejo, Agrowisata Petik Jeruk menawarkan pengalaman autentik berada di tengah hamparan kebun jeruk seluas puluhan hektare di lereng pegunungan yang sangat sejuk. Varietas unggulan yang dibudidayakan di sini adalah Jeruk Keprok Batu 55 dan Jeruk Babal, yang terkenal akan perpaduan rasa manis segar dan bulir yang melimpah. Udara pegunungan yang mencapai 18-22 derajat celcius menjadikan wisata ini sangat cocok untuk melepaskan penat dari hiruk pikuk perkotaan.
