INSERT INTO `produk` (`id`, `nama`, `deskripsi`, `harga`, `gambar`, `stok`, `created_at`, `updated_at`, `kategori`, `shares`, `whatsapp`, `link_shopee`, `link_tokopedia`, `link_marketplace_lainnya`) VALUES
('1', 'Kopi Arabika Lereng Kawi (200gr)', 'Biji kopi Arabika Selorejo dipanen dari ketinggian 1.200 mdpl di lereng Gunung Kawi, menghasilkan profil rasa yang kompleks dengan dominasi fruity notes seperti apel hijau dan blackberry. Diproses secara natural untuk menjaga karakteristik keasaman yang segar dan tubuh (body) yang sedang, kopi ini menjadi pilihan utama bagi para pecinta kopi specialty yang mencari citarasa autentik pegunungan Malang.', '35000', 'https://images.unsplash.com/photo-1559056199-641a0ac8b55e?w=800&q=80', '100', '2026-04-13 19:08:30', '2026-07-12 11:47:44', 'Minuman', '31', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('2', 'Jeruk Keprok Batu 55 (1 Kg)', 'Sebagai ikon agrowisata Selorejo, Jeruk Keprok Batu 55 menawarkan perpaduan sempurna antara rasa manis yang kuat dengan sentuhan sensasi asam segar. Buahnya memiliki kulit yang cukup tebal berwarna kuning jingga yang menarik dan mudah dikupas, serta daging buah yang kenyal dan kaya sari buah. Jeruk ini ditanam dengan praktik pertanian ramah lingkungan untuk memastikan setiap gigitannya aman dan menyehatkan bagi keluarga.', '25000', 'https://images.unsplash.com/photo-1557844352-761f2565b576?w=800&q=80', '150', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Jeruk Segar', '6', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('3', 'Jeruk Baby Java (1 Kg)', 'Jeruk Baby Java Selorejo dikenal sebagai jeruk paling bersahabat bagi pencernaan si kecil berkat kadar asamnya yang sangat rendah namun memiliki tingkat kemanisan alami yang tinggi. Kaya akan Vitamin C dan antioksidan, jeruk ini menjadi favorit untuk dijadikan air perasan bagi bayi (MPASI) maupun sebagai sumber hidrasi harian yang menyegarkan. Tekstur kulitnya yang halus dan daging buahnya yang lembut memberikan kualitas sari buah maksimal di setiap perasannya.', '20000', 'https://images.unsplash.com/photo-1544145945-f904253d0c71?w=800&q=80', '120', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Jeruk Segar', '34', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('4', 'Keripik Mbote/Talas BUMDes', 'Keripik Mbote adalah camilan warisan leluhur Desa Selorejo yang dibuat dari Umbi Talas (Mbote) pilihan hasil bumi lereng Kawi. Diolah secara higienis oleh kelompok ibu-ibu PKK desa, umbi talas diiris tipis secara presisi dan direndam dalam bumbu rempah rahasia sebelum digoreng hingga mencapai tingkat kerenyahan maksimal. Tanpa bahan pengawet dan MSG, keripik ini menawarkan rasa gurih autentik yang sulit dilupakan.', '15000', 'https://images.unsplash.com/photo-1599599810769-bcde5a160d32?w=800&q=80', '80', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Makanan', '5', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('5', 'Jamu Instan Temulawak & Jahe', 'Produk unggulan dari Kelompok Wanita Tani (KWT) Selorejo ini menghadirkan kepraktisan minuman kesehatan tradisional dalam bentuk serbuk instan yang mudah diseduh. Campuran Temulawak, Jahe Merah, dan Gula Aren pilihan diolah secara tradisional namun tetap menjaga standar kebersihan untuk memberikan manfaat maksimal bagi daya tahan tubuh dan kehangatan sistem pencernaan. Cocok dinikmati setiap pagi sebagai pendamping gaya hidup sehat Anda.', '20000', 'https://images.unsplash.com/photo-1599321427976-5d63f034ee51?w=800&q=80', '90', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Minuman', '16', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('6', 'Jeruk Keprok Keranjang Gift', 'Hadirkan kehangatan khas Desa Selorejo melalui paket hadiah eksklusif Jeruk Keprok Keranjang. Berisi 5kg jeruk pilihan kualitas super yang dikemas dalam keranjang bambu tradisional (besek) yang ramah lingkungan dan estetik. Pilihan tepat sebagai oleh-oleh premium atau hantaran spesial bagi kerabat dan kolega, mencerminkan ketulusan hasil bumi langsung dari tangan petani lokal kami.', '135000', 'https://images.unsplash.com/photo-1543328225-b4ee54e173bd?w=800&q=80', '40', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Olahan Buah', '22', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('7', 'Madu Murni Bunga Jeruk', 'Madu Bunga Jeruk Selorejo merupakan jenis madu monofloral langka yang dihasilkan oleh lebah penghisap nektar bunga pohon jeruk yang mekar secara serempak. Memiliki aroma flora yang harum dengan sentuhan rasa yang ringan dan sedikit citrusy, madu ini kaya akan flavonoid dan enzim aktif yang baik untuk kesehatan lambung dan imunitas. Teksturnya yang jernih dan kemampuannya mengkristal dengan halus menjadi segel keaslian madu murni tanpa campuran.', '85000', 'https://images.unsplash.com/photo-1587049352846-4a222e784d38?w=800&q=80', '50', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Makanan', '37', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('8', 'Sari Jeruk Selorejo Botolan', 'Nikmati kesegaran murni 100% buah jeruk Selorejo dalam setiap botolnya tanpa tambahan pemanis buatan maupun pengawet. Menggunakan teknologi pengolahan suhu rendah untuk menjaga kandungan vitamin dan nutrisi alami tetap utuh, sari jeruk ini menawarkan rasa manis-segar yang konsisten. Praktis untuk dibawa beraktivitas dan menjadi solusi harian bagi Anda yang membutuhkan asupan Vitamin C instan di tengah kesibukan.', '12000', 'https://images.unsplash.com/photo-1613478223719-2ab802602423?w=800&q=80', '200', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Minuman', '20', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi'),
('9', 'Pupuk Organik Cair Desa', 'Rahasia kesuburan agrowisata kami kini tersedia untuk kebun Anda sendiri. Pupuk Organik Cair (POC) Desa Selorejo diolah dari limbah pertanian dan mikroorganisme lokal (MOL) yang terbukti ampuh meningkatkan kualitas pembungaan dan pembuahan tanaman jeruk. Selain ramah lingkungan, pupuk ini membantu memperbaiki pori-pori tanah dan menyediakan nutrisi esensial bagi tanaman agar tumbuh lebih kuat, tahan penyakit, dan berbuah lebat secara alami.', '45000', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?w=800&q=80', '60', '2026-04-13 19:08:30', '2026-07-10 13:49:08', 'Pertanian', '38', NULL, 'https://shopee.co.id/kopi-arabika-lereng-kawi', 'https://tokopedia.com/kopi-arabika-lereng-kawi', 'https://lazada.co.id/kopi-arabika-lereng-kawi');
INSERT INTO `berita` (`id`, `judul`, `slug`, `konten`, `gambar`, `kategori`, `tanggal`, `penulis`, `status_publish`, `views`, `likes`, `created_at`, `updated_at`, `dislikes`, `shares`) VALUES
('9', 'Pengembangan Website Desa Wisata Petik Jeruk Selorejo sebagai Media Promosi Digital Berkelanjutan dan Pelayanan Publik Desa', 'pengembangan-website-desa-wisata-petik-jeruk-selorejo-sebagai-media-promosi-digital-berkelanjutan-dan-pelayanan-publik-desa', '<p style="margin-bottom: 1.5rem; text-align: justify;"><b>Kelompok KKN Tematik Universitas Sebelas Maret (UNS) Surakarta Kelompok 178</b> berkolaborasi dengan Perangkat Desa Selorejo merancang dan meluncurkan program kerja utama berupa pengembangan website resmi Desa Wisata Petik Jeruk Selorejo di Kecamatan Dau, Kabupaten Malang. Kegiatan pengabdian ini bertujuan untuk mentransformasi sistem promosi wisata petik jeruk dan komoditas perkebunan tebu yang selama ini masih bersifat konvensional mulut ke mulut menjadi promosi digital berbasis teknologi yang berkelanjutan. Program ini selaras dengan Sustainable Development Goals (SDGs), khususnya SDG 8 (Pekerjaan Layak dan Pertumbuhan Ekonomi), SDG 9 (Industri, Inovasi, dan Infrastruktur Digital), SDG 11 (Kota dan Komunitas Berkelanjutan), serta SDG 17 (Kemitraan untuk Mencapai Tujuan).</p>
