INSERT INTO `peta_titiks` (`id`, `nama`, `kategori`, `dusun`, `deskripsi`, `foto`, `latitude`, `longitude`, `is_wisata_unggulan`, `sumber_data`, `urutan_tampil`, `umkm_id`, `wisata_id`, `created_at`, `updated_at`, `gmaps_link`) VALUES
('1', 'Bumi Perkemahan Bedengan', 'camping_ground', 'gumuk', 'Area bumi perkemahan dengan nuansa hutan pinus yang asri. Terletak di bagian barat Desa Selorejo, dekat perbatasan Desa Petungsewu. Cocok untuk kegiatan berkemah, outbound, dan wisata alam.', 'images/tempat_penting/(Gumuk) Bumi Perkemahan Bedengan.webp', NULL, NULL, '1', 'Observasi Lapangan 2026', '1', NULL, '2', '2026-08-10 16:10:33', '2026-08-11 14:08:04', NULL),
('2', 'Hovsky 360 View', 'cafe', 'selokerto', 'Cafe bertingkat dengan pemandangan 360 derajat Desa Selokerto dan sekitarnya. Buka malam hari dengan pencahayaan yang menarik, menjadi spot foto favorit wisatawan.', NULL, NULL, NULL, '1', 'Observasi Lapangan 2026', '2', '107', NULL, '2026-08-10 16:10:33', '2026-08-10 16:10:33', NULL),
('3', 'Wisata Agro Petik Jeruk', 'toko_buah_wisata_jeruk', 'krajan', 'Wisata agro petik jeruk unggulan di Desa Selorejo, berlokasi dekat Gapura Desa. Pengunjung dapat langsung memetik jeruk segar dari pohon dan membeli hasil panen sebagai oleh-oleh.', 'images/JerukSelorejo.jpg', NULL, NULL, '1', 'Observasi Lapangan 2026', '3', '19', '1', '2026-08-10 16:10:33', '2026-08-11 14:08:04', NULL),
('4', 'Wisata Petik Jeruk Adila', 'toko_buah_wisata_jeruk', 'gumuk', 'Kebun petik jeruk dengan brand "Adila" di Dusun Gumuk. Menawarkan pengalaman memetik jeruk langsung dari pohon dengan kemasan produk yang menarik.', NULL, NULL, NULL, '1', 'Observasi Lapangan 2026', '4', '6', NULL, '2026-08-10 16:10:33', '2026-08-10 16:10:33', NULL),
('5', 'Wisata Petik Jeruk Haji Umin', 'toko_buah_wisata_jeruk', 'krajan', 'Wisata petik jeruk milik Haji Umin di Dusun Krajan. Salah satu kebun jeruk tertua dan terpercaya di Desa Selorejo dengan hasil panen berkualitas tinggi.', NULL, NULL, NULL, '1', 'Observasi Lapangan 2026', '5', '26', NULL, '2026-08-10 16:10:33', '2026-08-10 16:10:33', NULL),
('6', 'Wisata Petik Jeruk Pak Muji', 'toko_buah_wisata_jeruk', 'krajan', 'Kebun wisata petik jeruk Pak Muji berlokasi di Dusun Krajan. Pengunjung dapat menikmati suasana kebun jeruk yang rindang sambil memetik jeruk segar.', NULL, NULL, NULL, '1', 'Observasi Lapangan 2026', '6', '30', NULL, '2026-08-10 16:10:33', '2026-08-10 16:10:33', NULL),
('7', 'Wisata Petik Jeruk Pak Suwaji', 'toko_buah_wisata_jeruk', 'krajan', 'Wisata petik jeruk Pak Suwaji berlokasi di Dusun Krajan dekat perbatasan Desa Gadingkulon. Memiliki gapura/gerbang masuk yang ikonik dan akses jalan yang mudah.', NULL, NULL, NULL, '1', 'Observasi Lapangan 2026', '7', '20', NULL, '2026-08-10 16:10:33', '2026-08-10 16:10:33', NULL),
('8', 'Strawberry Jumbo', 'toko_buah_wisata_jeruk', 'gumuk', 'Usaha Dagang Strawberry di Dusun Gumuk, Desa Selorejo. Pemilik: Pak Supri.', 'images/umkm/gumuk_1_strawberry_jumbo.jpg', NULL, NULL, '0', 'Pendataan & Pemetaan UMKM Desa 2026', '50', '1', NULL, '2026-08-10 16:10:33', '2026-08-10 16:10:33', NULL),
